Now I see the rule: background cells change to 3 only if they lie strictly between two markers of the non-background color in the same row or in the same column; markers and other background cells keep their color.

```python
def transform(grid):
    rows = len(grid); cols = len(grid[0])
    counts = {}
    for r in grid:
        for v in r:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r in range(rows):
        mr = [c for c in range(cols) if grid[r][c] != bg]
        for c in range(cols):
            if grid[r][c] != bg: continue
            if any(x < c for x in mr) and any(x > c for x in mr):
                out[r][c] = 3
    for c in range(cols):
        mc = [r for r in range(rows) if grid[r][c] != bg]
        for r in range(rows):
            if grid[r][c] != bg: continue
            if any(x < r for x in mc) and any(x > r for x in mc):
                out[r][c] = 3
    return out
```

